import { build } from 'esbuild';
import { readFileSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const p = (x) => join(root, x);

mkdirSync(p('src/generated'), { recursive: true });
mkdirSync(p('tmp'), { recursive: true });

// 1. Bundle the site client script (runs inside exported pages)
await build({
  entryPoints: [p('src/client.ts')],
  bundle: true,
  format: 'iife',
  target: 'es2020',
  minify: true,
  outfile: p('tmp/client.js'),
  logLevel: 'silent',
});

const clientJs = readFileSync(p('tmp/client.js'), 'utf8');
writeFileSync(
  p('src/generated/client-bundle.ts'),
  `// Generated by esbuild.config.mjs - do not edit\nexport default ${JSON.stringify(clientJs)};\n`,
);

// 2. Embed the theme stylesheet as a TS string
const themeCss = readFileSync(p('src/theme.css'), 'utf8');
writeFileSync(
  p('src/generated/theme-css.ts'),
  `// Generated by esbuild.config.mjs - do not edit\nexport default ${JSON.stringify(themeCss)};\n`,
);

// 3. Bundle the plugin itself
await build({
  entryPoints: [p('src/main.ts')],
  bundle: true,
  platform: 'node',
  external: ['obsidian', 'electron', '@codemirror/autocomplete', '@codemirror/collab', '@codemirror/commands', '@codemirror/language', '@codemirror/lint', '@codemirror/search', '@codemirror/state', '@codemirror/view', '@lezer/common', '@lezer/highlight', '@lezer/lr'],
  format: 'cjs',
  target: 'es2020',
  outfile: p('main.js'),
  logLevel: 'info',
});

rmSync(p('tmp'), { recursive: true, force: true });
console.log('build done');
